Here is the commit message:
futex: Clear stale exiting pointer in futex_lock_pi() retry
 path

Fuzzying/stressing futexes triggered:

    WARNING: kernel/futex/core.c:825 at wait_for_owner_exiting+0x7a/0x80, CPU#11: futex_lock_pi_s/524

When futex_lock_pi_atomic() sees the owner is exiting, it returns -EBUSY
and stores a refcounted task pointer in 'exiting'.

After wait_for_owner_exiting() consumes that reference, the local pointer
is never reset to nil. Upon a retry, if futex_lock_pi_atomic() returns a
different error, the bogus pointer is passed to wait_for_owner_exiting().

  CPU0			     CPU1		       CPU2
  futex_lock_pi(uaddr)
  // acquires the PI futex
  exit()
    futex_cleanup_begin()
      futex_state = EXITING;
			     futex_lock_pi(uaddr)
			       futex_lock_pi_atomic()
				 attach_to_pi_owner()
				   // observes EXITING
				   *exiting = owner;  // takes ref
				   return -EBUSY
			       wait_for_owner_exiting(-EBUSY, owner)
				 put_task_struct();   // drops ref
			       // exiting still points to owner
			       goto retry;
			       futex_lock_pi_atomic()
				 lock_pi_update_atomic()
				   cmpxchg(uaddr)
					*uaddr ^= WAITERS // whatever
				   // value changed
				 return -EAGAIN;
			       wait_for_owner_exiting(-EAGAIN, exiting) // stale
				 WARN_ON_ONCE(exiting)

Fix this by resetting upon retry, essentially aligning it with requeue_pi.

Fixes: 3ef240eaff36 ("futex: Prevent exit livelock")
Signed-off-by: Davidlohr Bueso <dave@stgolabs.net>
Signed-off-by: Thomas Gleixner <tglx@kernel.org>
Cc: stable@vger.kernel.org
Link: https://patch.msgid.link/20260326001759.4129680-1-dave@stgolabs.net

Here is the root cause:
In futex_lock_pi(), the local 'exiting' pointer is not reset to NULL on retry. After wait_for_owner_exiting() drops the reference, the stale pointer remains. On a subsequent retry, if futex_lock_pi_atomic() returns an error that does not update 'exiting', the stale pointer is passed to wait_for_owner_exiting() again, triggering a WARN_ON.

Here is the patch:
  */
 int futex_lock_pi(u32 __user *uaddr, unsigned int flags, ktime_t *time, int trylock)
 {
 	struct hrtimer_sleeper timeout, *to;
-	struct task_struct *exiting = NULL;
+	struct task_struct *exiting;
 	struct rt_mutex_waiter rt_waiter;
 	struct futex_q q = futex_q_init;
 	DEFINE_WAKE_Q(wake_q);
 	int res, ret;

 	if (!IS_ENABLED(CONFIG_FUTEX_PI))
 		return -ENOSYS;

 	if (refill_pi_state_cache())
 		return -ENOMEM;

 	to = futex_setup_timer(time, &timeout, flags, 0);

 retry:
+	exiting = NULL;
 	ret = get_futex_key(uaddr, flags, &q.key, FUTEX_WRITE);
 	if (unlikely(ret != 0))
 		goto out;

 retry_private:
 	if (1) {
 		CLASS(hb, hb)(&q.key);

 		futex_q_lock(&q, hb);

 		ret = futex_lock_pi_atomic(uaddr, hb, &q.key, &q.pi_state, current,
 					   &exiting, 0);
 		if (unlikely(ret)) {
 			/*
 			 * Atomic work succeeded and we got the lock,
 			 * or failed. Either way, we do _not_ block.
 			 */
 			switch (ret) {
 			case 1:
 				/* We got the lock. */
 				ret = 0;
 				goto out_unlock_put_key;
 			case -EFAULT:
 				goto uaddr_faulted;
 			case -EBUSY:
 			case -EAGAIN:
 				/*
 				 * Two reasons for this:
 				 * - EBUSY: Task is exiting and we just wait for the
 				 *   exit to complete.
 				 * - EAGAIN: The user space value changed.
 				 */
 				futex_q_unlock(hb);
 				/*
 				 * Handle the case where the owner is in the middle of
 				 * exiting. Wait for the exit to complete otherwise
 				 * this task might loop forever, aka. live lock.
 				 */
 				wait_for_owner_exiting(ret, exiting);
 				cond_resched();
 				goto retry;
 			default:
 				goto out_unlock_put_key;
 			}
 		}

 		WARN_ON(!q.pi_state);

 		/*
 		 * Only actually queue now that the atomic ops are done:
 		 */
 		__futex_queue(&q, hb, current);

 		if (trylock) {
 			ret = rt_mutex_futex_trylock(&q.pi_state->pi_mutex);
 			/* Fixup the trylock return value: */
 			ret = ret ? 0 : -EWOULDBLOCK;
 			goto no_block;
 		}

 		/*
 		 * Caution; releasing @hb in-scope. The hb->lock is still locked
 		 * while the reference is dropped. The reference can not be dropped
 		 * after the unlock because if a user initiated resize is in progress
 		 * then we might need to wake him. This can not be done after the
 		 * rt_mutex_pre_schedule() invocation. The hb will remain valid because
 		 * the thread, performing resize, will block on hb->lock during
 		 * the requeue.
 		 */
 		futex_hash_put(no_free_ptr(hb));
 		/*
 		 * Must be done before we enqueue the waiter, here is unfortunately
 		 * under the hb lock, but that *should* work because it does nothing.
 		 */
 		rt_mutex_pre_schedule();

 		rt_mutex_init_waiter(&rt_waiter);

 		/*
 		 * On PREEMPT_RT, when hb->lock becomes an rt_mutex, we must not
 		 * hold it while doing rt_mutex_start_proxy(), because then it will
 		 * include hb->lock in the blocking chain, even through we'll not in
 		 * fact hold it while blocking. This will lead it to report -EDEADLK
 		 * and BUG when futex_unlock_pi() interleaves with this.
 		 *
 		 * Therefore acquire wait_lock while holding hb->lock, but drop the
 		 * latter before calling __rt_mutex_start_proxy_lock(). This
 		 * interleaves with futex_unlock_pi() -- which does a similar lock
 		 * handoff -- such that the latter can observe the futex_q::pi_state
 		 * before __rt_mutex_start_proxy_lock() is done.
 		 */
 		raw_spin_lock_irq(&q.pi_state->pi_mutex.wait_lock);
 		spin_unlock(q.lock_ptr);
 		/*
 		 * __rt_mutex_start_proxy_lock() unconditionally enqueues the @rt_waiter
 		 * such that futex_unlock_pi() is guaranteed to observe the waiter when
 		 * it sees the futex_q::pi_state.
 		 */
 		ret = __rt_mutex_start_proxy_lock(&q.pi_state->pi_mutex, &rt_waiter, current, &wake_q);
 		raw_spin_unlock_irq_wake(&q.pi_state->pi_mutex.wait_lock, &wake_q);

 		if (ret) {
 			if (ret == 1)
 				ret = 0;
 			goto cleanup;
 		}

 		if (unlikely(to))
 			hrtimer_sleeper_start_expires(to, HRTIMER_MODE_ABS);

 		ret = rt_mutex_wait_proxy_lock(&q.pi_state->pi_mutex, to, &rt_waiter);

 cleanup:
 		/*
 		 * If we failed to acquire the lock (deadlock/signal/timeout), we must
 		 * unwind the above, however we canont lock hb->lock because
 		 * rt_mutex already has a waiter enqueued and hb->lock can itself try
 		 * and enqueue an rt_waiter through rtlock.
 		 *
 		 * Doing the cleanup without holding hb->lock can cause inconsistent
 		 * state between hb and pi_state, but only in the direction of not
 		 * seeing a waiter that is leaving.
 		 *
 		 * See futex_unlock_pi(), it deals with this inconsistency.
 		 *
 		 * There be dragons here, since we must deal with the inconsistency on
 		 * the way out (here), it is impossible to detect/warn about the race
 		 * the other way around (missing an incoming waiter).
 		 *
 		 * What could possibly go wrong...
 		 */
 		if (ret && !rt_mutex_cleanup_proxy_lock(&q.pi_state->pi_mutex, &rt_waiter))
 			ret = 0;

 		/*
 		 * Now that the rt_waiter has been dequeued, it is safe to use
 		 * spinlock/rtlock (which might enqueue its own rt_waiter) and fix up
 		 * the
 		 */
 		futex_q_lockptr_lock(&q);
 		/*
 		 * Waiter is unqueued.
 		 */
 		rt_mutex_post_schedule();
 no_block:
 		/*
 		 * Fixup the pi_state owner and possibly acquire the lock if we
 		 * haven't already.
 		 */
 		res = fixup_pi_owner(uaddr, &q, !ret);
 		/*
 		 * If fixup_pi_owner() returned an error, propagate that.  If it acquired
 		 * the lock, clear our -ETIMEDOUT or -EINTR.
 		 */
 		if (res)
 			ret = (res < 0) ? res : 0;

 		futex_unqueue_pi(&q);
 		spin_unlock(q.lock_ptr);
 		if (q.drop_hb_ref) {
 			CLASS(hb, hb)(&q.key);
 			/* Additional reference from futex_unlock_pi() */
 			futex_hash_put(hb);
 		}
 		goto out;

 out_unlock_put_key:
 		futex_q_unlock(hb);
 		goto out;

 uaddr_faulted:
 		futex_q_unlock(hb);

 		ret = fault_in_user_writeable(uaddr);
 		if (ret)
 			goto out;

 		if (!(flags & FLAGS_SHARED))
 			goto retry_private;

 		goto retry;
 	}

 out:
 	if (to) {
 		hrtimer_cancel(&to->timer);
 		destroy_hrtimer_on_stack(&to->timer);
 	}
 	return ret != -EINTR ? ret : -ERESTARTNOINTR;
 }



